"""specs_s200030.py - Sonnet-w2 family G (generated by mkfamG.py). The stack-local object L is observed by the hooks: 0x59a9b0 (ctor, ecx = L, recorded as a stack marker) fills L with
random values; the slot 0x1c stub (arg = L) and 0x4ff9d0 (ecx = L) read L back (3 dwords + byte 0xc) into the call log, so a wrong initial L or a wrong pointer is a mismatch.
Fake outer SEH records 0-2; the SEH chain at each call is recorded; fs:[0] compared. ret=None (void)."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _lread(emu, a):
    return (emu.r32(a), emu.r32(a + 4), emu.r32(a + 8), emu.rbytes(a + 0xc, 1)[0])


def _gen(c, glob):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    sr1, sr2, sr3 = seh_record(c, 2), seh_record(c, 2), seh_record(c, 2)

    def ctor_side(emu, k):
        a = emu.reg('ecx')
        emu.calllog.append(('L0', _lread(emu, a)))
        emu.w32(a, r.getrandbits(32)); emu.w32(a + 4, r.getrandbits(32)); emu.w32(a + 8, r.getrandbits(32))
        emu.wbytes(a + 0xc, bytes([r.getrandbits(8)]))
        sr1(emu, k)

    def slot_side(emu, k):
        emu.calllog.append(('L1', _lread(emu, emu.arg32(0))))
        sr2(emu, k)

    def dtor_side(emu, k):
        emu.calllog.append(('L2', _lread(emu, emu.reg('ecx'))))
        sr3(emu, k)
    hook_rec(c, 0x59a9b0, 1, ret=r.getrandbits(32), pop=4, this='mark', side=ctor_side)
    hook_rec(c, 0x4ff9d0, 0, ret=r.getrandbits(32), this='mark', side=dtor_side)
    o = obj(c, 0x40, {0x1c: pystub(c, 1, ret=r.getrandbits(32), this=True, side=slot_side, stackmark=(0,))}, nslots=0x10)
    c.emu.w32(glob, r.choice([0, 0, 1, r.getrandbits(32)]))
    return [o]


S(0x5044c0, 'GUESS famG 0x5044c0', 'thiscall', None, ret=None, gen=lambda c, g=0x700e70: _gen(c, g), note='batch200030')
